function applyDiscount(price: number, discount?: number): number {
  if (!discount) return price;
  return Math.round((price - price * discount) * 100) / 100;
}

interface PaymentProvider { process(amount:number): boolean }

class StripeProvider implements PaymentProvider {
  process(amount:number) { /* stripe calls */ return true; }
}

class PaymentFactory {
  static create(provider: string): PaymentProvider {
    if (provider === 'stripe') return new StripeProvider();
    throw new Error('Unknown provider');
  }
}

class OrderService {
  constructor(private providerName: string) {}
  pay(amount:number) {
    const provider = PaymentFactory.create(this.providerName);
    return provider.process(amount);
  }
}

